create table if not exists public.v21_purchase_plan_allocations (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,purchase_plan_line_id uuid not null references public.purchase_plan_lines(id) on delete cascade,location_id uuid not null references public.locations(id),allocated_quantity numeric(24,8) not null check(allocated_quantity>0),unit text not null,source_routing_run_id uuid references public.routing_execution_logs(id),created_at timestamptz not null default now(),unique(purchase_plan_line_id,location_id)); create index if not exists idx_v21_plan_allocations_business_location on public.v21_purchase_plan_allocations(business_id,location_id,created_at desc); create table if not exists public.v21_purchase_order_allocations (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,purchase_order_line_id uuid not null references public.purchase_order_lines(id) on delete cascade,location_id uuid not null references public.locations(id),allocated_quantity numeric(24,8) not null check(allocated_quantity>0),unit text not null,source_routing_run_id uuid references public.routing_execution_logs(id),created_at timestamptz not null default now(),unique(purchase_order_line_id,location_id)); create index if not exists idx_v21_po_allocations_business_location on public.v21_purchase_order_allocations(business_id,location_id,created_at desc); alter table public.v21_purchase_plan_allocations enable row level security; alter table public.v21_purchase_order_allocations enable row level security; drop policy if exists v21_plan_alloc_select on public.v21_purchase_plan_allocations; create policy v21_plan_alloc_select on public.v21_purchase_plan_allocations for select using(is_member(business_id)); drop policy if exists v21_po_alloc_select on public.v21_purchase_order_allocations; create policy v21_po_alloc_select on public.v21_purchase_order_allocations for select using(is_member(business_id)); create or replace view public.view_v21_fulfillment_allocations with(security_invoker=true) as select 'internal_transfer'::text track,st.business_id,st.id reference_id,st.transfer_number reference_number,st.source_location_id,st.destination_location_id,l.ingredient_id,l.quantity,l.unit,st.status::text status,st.created_at from public.stock_transfers st join public.stock_transfer_lines l on l.stock_transfer_id=st.id union all select 'external_purchase'::text,po.business_id,po.id,po.order_number,a.location_id,null::uuid,pol.ingredient_id,a.allocated_quantity,a.unit,po.status::text,po.created_at from public.v21_purchase_order_allocations a join public.purchase_order_lines pol on pol.id=a.purchase_order_line_id join public.purchase_orders po on po.id=pol.purchase_order_id;